refused_program.body:
set -e
git fetch {upstream_remote}
if [ -z "$(git rev-parse --verify --quiet MERGE_HEAD)" ]; then
  git merge --no-edit {upstream_remote}/{upstream_branch} || true
fi
base=$(git merge-base HEAD {upstream_remote}/{upstream_branch})
while IFS= read -r -d '' f; do
  tmp=$(mktemp -d)
  git show {upstream_remote}/{upstream_branch}:"$f" > "$tmp/up"
  git show HEAD:"$f" > "$tmp/local"
  git diff --unified=0 --no-color "$base" HEAD -- "$f" |
    awk '/^@@/ { if (h && !m) for (i=1;i<=n;i++) print a[i]; h=1; m=0; n=0; next } h && /^-/ { m=1; next } h && /^\+/ { a[++n]=substr($0,2) } END { if (h && !m) for (i=1;i<=n;i++) print a[i] }' > "$tmp/adds"
  awk -v first="$tmp/up" -v addfile="$tmp/adds" '
    FILENAME==first { up[++nu]=$0; ups[$0]=1; next }
    { loc[++nl]=$0 }
    END {
      na=0
      while ((getline line < addfile) > 0) {
        if (line in ups) continue
        if (line in seen) continue
        seen[line]=1
        adds[++na]=line
      }
      for (j=1;j<=na;j++) {
        ai=0
        li=0
        for (k=1;k<=nl;k++) if (loc[k]==adds[j]) { li=k; break }
        if (li>0) {
          for (k=li-1;k>=1;k--) {
            if (loc[k] in ups) {
              for (m=1;m<=nu;m++) if (up[m]==loc[k]) ai=m
              break
            }
          }
        }
        anchor[j] = (ai>0) ? ai : -1
      }
      for (j=1;j<=na;j++) if (anchor[j]==-1) print adds[j]
      for (i=1;i<=nu;i++) {
        print up[i]
        for (j=1;j<=na;j++) if (anchor[j]==i) print adds[j]
      }
    }
  ' "$tmp/up" "$tmp/local" > "$tmp/resolved"
  cat "$tmp/resolved" > "$f"
  git add -- "$f"
  rm -rf "$tmp"
done < <(git diff --name-only --diff-filter=U -z)
if [ -n "$(git rev-parse --verify --quiet MERGE_HEAD)" ]; then
  git commit --no-edit
fi
